import type { Identity } from "@/content/projects"

/** Nicell's wordmark, drawn as single strokes like on nicell.com.br. */
export function NicellWordmark({ className }: { className?: string }) {
  return (
    <svg viewBox="6 5 184 70" role="img" aria-label="Nicell" className={className}>
      <g fill="none" stroke="#15171c" strokeWidth="5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M14 56V32.5L50 67.5V32.5" />
        <path d="M64 67.5V32.5" />
        <path d="M107.87 37.63A17.5 17.5 0 1 0 107.87 62.37" />
        <path d="M118.9 50H153.9A17.5 17.5 0 1 0 148.77 62.37" />
        <path d="M167.9 67.5V12.5" />
        <path d="M181.9 67.5V12.5" />
      </g>
    </svg>
  )
}

/** Roarch's room plan: the walls, centred on a 34 unit square, and the door gap in the right wall. Units of a 64 grid. */
export const roarchPlan = {
  walls: "M15 15 H49 M15 15 V49 M15 49 H49 M49 15 V26 M49 38 V49",
  door: "M49 26 V38",
  wall: 7,
  doorWidth: 5,
}

/** The plan mark's two strokes, for an svg on the 64 grid. */
export function RoarchPlan({ walls, door }: { walls: string; door: string }) {
  return (
    <>
      <path d={roarchPlan.walls} fill="none" stroke={walls} strokeWidth={roarchPlan.wall} strokeLinecap="square" />
      <path d={roarchPlan.door} fill="none" stroke={door} strokeWidth={roarchPlan.doorWidth} />
    </>
  )
}

